def search_substr(fullText, searchText, allowOverlap=True):
    if not searchText:
        return 0

    count = 0
    n = len(fullText)
    m = len(searchText)

    if allowOverlap:
        for i in range(n - m + 1):
            if fullText[i:i+m] == searchText:
                count += 1
    else:
        i = 0
        while i <= n - m:
            if fullText[i:i+m] == searchText:
                count = count + 1
                i = i + m
            else:
                i = i + 1

    return count
